import { readFileSync } from 'node:fs';
import { Client } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import { StdioClientTransport } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
const cfg = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const client = new Client({ name: 'local-install-check', version: '1.0.0' });
const t = new StdioClientTransport({ command: cfg.command, args: cfg.args, env: cfg.env, cwd: cfg.cwd, stderr: 'inherit' });
try {
  await client.connect(t);
  const { tools } = await client.listTools();
  for (const name of ['remember', 'recall', 'forget']) if (!tools.some(tool => tool.name === name)) throw new Error(`MCP tool not advertised: ${name}`);
  const result = await client.callTool({ name: 'recall', arguments: { query: 'cobalt lantern verification marker' } });
  if (result.isError || !JSON.stringify(result).includes('OpenClaw GBrain installation check: cobalt lantern verification marker')) throw new Error(JSON.stringify(result));
  console.log(JSON.stringify({ mcp: 'recall confirmed', toolCount: tools.length, marker: 'cobalt lantern verification marker' }));
} finally {
  await client.close();
}

